class Solution:
    def subarraySum(self, nums: List[int], k: int) -> int:
        count = 0
        hash_ = {0: 1}
        preSum = 0
        for i in range(len(nums)):
            preSum += nums[i]
            if hash_.get(preSum - k, 0) > 0:
                count += hash_[preSum - k]
            hash_[preSum] = hash_.get(preSum, 0) + 1
        return count

