class Solution:
    def subarraySum(self, nums: List[int], k: int) -> int:
        count = 0
        for start in range(len(nums)):
            sum_ = 0
            for end in range(start, -1, -1):
                sum_ += nums[end]
                if sum_ == k:
                    count += 1
        return count

class Solution:
    def subarraySum(self, nums: List[int], k: int) -> int:
        count, pre = 0, 0
        m = {0: 1}
        for i in range(len(nums)):
            pre += nums[i]
            if pre - k in m:
                count += m[pre - k]
            m[pre] = m.get(pre, 0) + 1
        return count
